def play_song():
    print("👉 请在 5 秒内切换到光遇窗口，并确保键盘输入法为【英文】...")
    for i in range(5, 0, -1):
        print(f"{i}...")
        time.sleep(1)
    
    print("🎵 脚本启动，正在为你自动演奏新曲目...")
    
    for notes, ms_delay in song_script:
        # 将毫秒级延迟转换为秒（例如 476ms -> 0.476s）
        base_delay = ms_delay / 1000.0
        
        # 触发物理按键
        if len(notes) > 1:
            # 💡 拟人化细节 1：多键齐奏时产生 3~7 毫秒的极速随机落键时差，弹奏更有滚奏的颗粒感
            for note in notes:
                if note in NOTE_MAPPING:
                    keyboard.press(NOTE_MAPPING[note])
                    time.sleep(random.uniform(0.003, 0.007))
        else:
            if notes[0] in NOTE_MAPPING:
                keyboard.press(NOTE_MAPPING[notes[0]])
        
        # 保持按压 0.05 秒，确保触控判定生效
        time.sleep(0.05)
        
        # 释放按键
        for note in notes:
            if note in NOTE_MAPPING:
                keyboard.release(NOTE_MAPPING[note])
            
        time.sleep(base_delay)

    print("✨ 新谱子演奏完毕！")

if __name__ == "__main__":
    play_song()